private static server str numOpenTrans()
    {
        str      numOpenTrans;
        DictView dictView  = new DictView(tableNum(METCustOpenItemsView));
        str      primaryDS = dictView.query().dataSourceTable(tableNum(CustTable)).name();

        numOpenTrans = strFmt(@"
                select count(*) from CustTransOpen where CustTransOpen.ACCOUNTNUM = %1 and custTransOpen.DATAAREAID = %2",
                SysComputedColumn::returnField(tableStr(METCustOpenItemsView), primaryDS, fieldStr(METCustOpenItemsView, AccountNum)),
                SysComputedColumn::returnField(tableStr(METCustOpenItemsView), primaryDS, fieldStr(METCustOpenItemsView, DataAreaId))
                             );

        return numOpenTrans;
    }

private static server str sumAmountOpenTrans()
{
