private static server str numDisputed()
{
    str      ret;
    DictView dictView  = new DictView(tableNum(METCustOpenItemsView));
    str      primaryDS = dictView.query().dataSourceTable(tableNum(CustTable)).name();

    ret = strFmt(@"
                SELECT count(*) FROM CUSTDISPUTE cd 
                INNER JOIN custtrans ct ON cd.CustTrans = ct.Recid 
                INNER JOIN custtransopen cto on cto.REFRECID = ct.Recid 
                where cd.STATUS = 1 and ct.ACCOUNTNUM = %1 and ct.DATAAREAID = %2",
                SysComputedColumn::returnField(tableStr(METCustOpenItemsView), primaryDS, fieldStr(METCustOpenItemsView, AccountNum)),
            SysComputedColumn::returnField(tableStr(METCustOpenItemsView), primaryDS, fieldStr(METCustOpenItemsView, DataAreaId))
              );
              
    return ret;
}

private static server str sumDisputed()
{
    str      ret;
    DictView dictView  = new DictView(tableNum(METCustOpenItemsView));
    str      primaryDS = dictView.query().dataSourceTable(tableNum(CustTable)).name();

    ret = strFmt(@"
                SELECT sum(cd.AMOUNTCUR) FROM CUSTDISPUTE cd
                INNER JOIN custtrans ct ON cd.CustTrans = ct.Recid
                INNER JOIN custtransopen cto on cto.REFRECID = ct.Recid
                WHERE cd.STATUS = 1 and ct.ACCOUNTNUM = %1 and ct.DATAAREAID = %2",
                SysComputedColumn::returnField(tableStr(METCustOpenItemsView), primaryDS, fieldStr(METCustOpenItemsView, AccountNum)),
                SysComputedColumn::returnField(tableStr(METCustOpenItemsView), primaryDS, fieldStr(METCustOpenItemsView, DataAreaId))
              );
              
    return ret;
}
